<script setup lang="ts">
import { onMounted, ref, computed } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, errorText, mutationId } from '../api';
import type { Diary } from '../../../packages/contracts/src/index.js';
import AtlasIcon from '../components/AtlasIcon.vue';
import ModalSheet from '../components/ModalSheet.vue';
const route = useRoute(), router = useRouter(), diary = ref<Diary | null>(null), error = ref(''), loading = ref(true), deleting = ref(false), confirm = ref(false); const deleteKey = mutationId();
const paragraphs = computed(() => diary.value?.body.split(/\n\s*\n/).filter(Boolean) ?? []);
async function load() { loading.value = true; error.value = ''; try { diary.value = await api<Diary>('/diaries/' + route.params.id); } catch (e) { error.value = errorText(e); } finally { loading.value = false; } }
onMounted(load);
async function remove() { deleting.value = true; error.value = ''; try { await api('/diaries/' + diary.value!.id, 'DELETE', { baseVersion: diary.value!.version, clientMutationId: deleteKey }); confirm.value = false; await router.replace('/memories'); } catch (e) { error.value = errorText(e); } finally { deleting.value = false; } }
</script>
<template><section class="flow-view"><header class="flow-topbar"><button class="icon-button" aria-label="返回回忆列表" @click="router.push('/memories')"><AtlasIcon name="back"/></button><h2>我的日记</h2><button class="icon-button" aria-label="编辑日记" :disabled="!diary" @click="router.push('/diaries/' + diary!.id + '/edit')"><AtlasIcon name="edit"/></button></header><div class="flow-scroll diary-reading"><p v-if="loading" class="form-intro">正在翻开日记…</p><p v-if="error && !confirm" class="flow-form-errors" role="alert">{{ error }}<button class="text-button" @click="load">重新加载</button></p><article v-if="diary" class="flow-journal"><p class="eyebrow">A MOMENT TO REMEMBER</p><h1>{{ diary.title }}</h1><div class="diary-reading-meta"><span>{{ diary.occurredOn || '日期未填写' }}</span><span>{{ diary.status === 'draft' ? '草稿' : '已记录' }}</span><span><AtlasIcon name="lock" :size="13"/>仅自己可见</span></div><div v-if="diary.association" class="diary-association"><RouterLink :to="'/journeys/' + diary.association.journeyId">{{ diary.association.journeyTitle }}</RouterLink><span v-if="diary.association.dayTitle"> · {{ diary.association.dayTitle }}</span><span v-if="diary.association.stopLabel"> · {{ diary.association.stopLabel }}</span><small v-if="diary.association.detached">原日期或地点已移除，名称快照仍保留。</small></div><p v-for="(paragraph,index) in paragraphs" :key="index" class="diary-paragraph">{{ paragraph }}</p><figure v-for="photo in diary.photos" :key="photo.mediaId" class="flow-journal-photo"><img v-if="photo.media" :src="photo.media.previewUrl" :alt="photo.caption || diary.title" :width="photo.media.width" :height="photo.media.height" loading="lazy"><figcaption v-if="photo.caption">{{ photo.caption }}</figcaption><a v-if="photo.media" :href="photo.media.originalUrl" class="private-download">下载私密原图</a></figure><p v-if="!diary.body && !diary.photos.length" class="muted">这篇日记还在等待新的内容。</p><div class="diary-reading-bottom"><small>最后保存：{{ new Date(diary.updatedAt).toLocaleString('zh-CN') }}</small><button class="text-button danger" @click="confirm = true">删除日记</button></div></article></div><ModalSheet v-if="confirm" title="删除这篇日记" :busy="deleting" @close="confirm = false"><p class="confirm-copy">确认删除“{{ diary?.title }}”及关联照片？行程与到访记录会保留。</p><p v-if="error" class="flow-form-errors" role="alert">{{ error }}</p><template #footer><button class="primary" :disabled="deleting" @click="remove">{{ deleting ? '正在删除…' : '确认删除日记与照片' }}</button></template></ModalSheet></section></template>
